// Access to the German and English UI strings (app_*.arb, generated by `flutter gen-l10n`).

import 'package:flutter/widgets.dart';

import '../theme/appearance.dart';
import 'app_localizations.dart';

export 'app_localizations.dart';

/// The app's supported locales; English (first) is the fallback for other device languages.
const List<Locale> appSupportedLocales = [Locale('en'), Locale('de')];

extension L10nContext on BuildContext {
  /// The strings of the current locale; English where no localizations are installed (widget tests).
  AppLocalizations get l10n => AppLocalizations.of(this) ?? L10n.current;
}

/// Strings for code outside the widget tree (services, notifications, errors made before they are shown):
/// the app's current language, kept up to date by the app root.
abstract final class L10n {
  static AppLocalizations _current = lookupAppLocalizations(const Locale('en'));

  static AppLocalizations get current => _current;

  /// Called by the app root whenever the resolved locale changes.
  static void update(Locale locale) {
    _current = lookupAppLocalizations(
      locale.languageCode == 'de' ? const Locale('de') : const Locale('en'),
    );
  }
}

extension AppearanceLabels on AppLocalizations {
  String modeLabel(AppearanceMode mode) => switch (mode) {
    AppearanceMode.system => modeSystem,
    AppearanceMode.light => modeLight,
    AppearanceMode.dark => modeDark,
  };

  String accentLabel(AccentChoice accent) => switch (accent) {
    AccentChoice.coderBlue => accentCoderBlue,
    AccentChoice.green => accentGreen,
    AccentChoice.yellow => accentYellow,
    AccentChoice.orange => accentOrange,
    AccentChoice.red => accentRed,
    AccentChoice.purple => accentPurple,
    AccentChoice.graphite => accentGraphite,
  };

  /// Language names stay in their own language ("Deutsch" in English too), as iOS shows them.
  String languageLabel(AppLanguage language) =>
      language.endonym ?? languageSystem;
}

extension IntlDateLocale on AppLocalizations {
  /// The locale for intl date formats. Plain English maps to en_US, whose date symbols intl always has
  /// (widget tests install no localizations, so no other date symbols are loaded there).
  String get dateLocale => localeName == 'en' ? 'en_US' : localeName;
}
